"""Hostile Firewall Bypass Benchmark Dataset (186 scenarios across 10 security categories).

Attacks the enforcement boundary and architecture rather than merely action classification.
Categories:
1. shell_process_bypass (indirect execution via python, node, ruby, perl, awk, find, etc.)
2. script_staging_bypass (staged scripts, Makefiles, package.json, tox, conftest hooks)
3. mcp_bypass (nested arguments, resources endpoints, tool aliases, unknown schemas)
4. filesystem_bypass (symlink swap, chains, hardlinks, TOCTOU, /proc/self, unicode)
5. network_bypass (HTTP 302 redirects to metadata/localhost, proxies, hex/octal/decimal IPs)
6. git_bypass (force push, insteadOf/pushInsteadOf, sshCommand, hooks, remote helpers)
7. github_effects_bypass (PR mutations, releases, label, close issue, comments with exfil)
8. secret_exfiltration_bypass (base64 with ==/=, hex, URL encodings, split across fields)
9. multistep_bypass (stateful composition: read secret -> send; stage script -> run)
10. fail_closed_robustness (null bytes, provider timeout, trace error, fail-closed)
"""

from __future__ import annotations

from typing import List
from drex_agent_firewall.benchmark.dataset import BenchmarkScenario
